<script setup lang="ts">
import {decorationUnitStyle} from '../../../../api/src/core/decoration-components.mjs'
import type {DecorationBlock,DecorationLink} from '../../../../api/src/core/decoration-types'
import {decorationOptions,visibleDecorationItems} from '../../../../api/src/core/decoration-options.mjs'
import DecorationIndicators from './DecorationIndicators.vue'
const props=defineProps<{block:DecorationBlock;imageUrl:(id:string)=>string;editable?:boolean;indicators?:boolean;variant?:'peek'|'normal'|'full'}>()
const emit=defineEmits<{navigate:[target:DecorationLink];current:[index:number]}>()
const viewport=shallowRef<HTMLElement|null>(null),current=ref(0),o=computed(()=>decorationOptions(props.block)),items=computed(()=>visibleDecorationItems(props.block))
let timer:ReturnType<typeof setInterval>|undefined,animation=0
function position(index:number){const element=viewport.value,child=element?.children[index] as HTMLElement|undefined;return element&&child?child.offsetLeft-(element.clientWidth-child.clientWidth)/2:0}
function go(index:number){const element=viewport.value;if(!element)return;cancelAnimationFrame(animation);const start=element.scrollLeft,end=Math.max(0,position(index)),time=performance.now();element.style.scrollSnapType='none';const step=(now:number)=>{const progress=Math.min(1,(now-time)/o.value.duration);element.scrollLeft=start+(end-start)*(1-Math.pow(1-progress,3));if(progress<1)animation=requestAnimationFrame(step);else{element.style.scrollSnapType='';current.value=index;emit('current',index)}};animation=requestAnimationFrame(step)}
function scrolling(){const el=viewport.value;if(!el)return;let closest=0;for(let i=1;i<items.value.length;i++)if(Math.abs(position(i)-el.scrollLeft)<Math.abs(position(closest)-el.scrollLeft))closest=i;current.value=closest;emit('current',closest)}
function restart(){clearInterval(timer);if(current.value>=items.value.length){current.value=0;go(0)}if(o.value.autoplay&&items.value.length>1)timer=setInterval(()=>go((current.value+1)%items.value.length),o.value.interval)}
onMounted(restart);watch(()=>[o.value.interval,o.value.autoplay,items.value.length],restart);onBeforeUnmount(()=>{clearInterval(timer);cancelAnimationFrame(animation)})
</script>
<template><div class="decoration-carousel" :class="variant" :style="decorationUnitStyle({height:block.height+'px'})"><div ref="viewport" class="carousel-viewport" @scroll="scrolling"><button v-for="(item,index) in items" :key="item.id" type="button" :class="{inactive:variant==='peek'&&current!==index}" :style="{borderRadius:o.imageRadiusTop+'px '+o.imageRadiusTop+'px '+o.imageRadiusBottom+'px '+o.imageRadiusBottom+'px'}" @click="!editable&&$emit('navigate',item.target)"><img :src="item.imageId||item.builtin?imageUrl((item.imageId||item.builtin)!):'/decoration/image-placeholder.svg'" :alt="item.label" :draggable="false"></button><img v-if="!items.length" src="/decoration/image-placeholder.svg" alt="选择轮播图片"></div><DecorationIndicators v-if="indicators" :count="items.length" :current="current" :options="o" class="carousel-indicators" @select="go"/></div></template>
<style scoped>.decoration-carousel{position:relative;overflow:hidden}.carousel-viewport{position:relative;display:flex;width:100%;height:100%;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;box-sizing:border-box}.carousel-viewport::-webkit-scrollbar{display:none}.carousel-viewport>button{padding:0;border:0;display:block;flex:0 0 100%;height:100%;scroll-snap-align:center;background:transparent;overflow:hidden;transition:transform .3s}.carousel-viewport img{display:block;width:100%;height:100%;object-fit:fill}.carousel-indicators{position:absolute;bottom:0;left:0;right:0}.peek .carousel-viewport{padding:0 calc(var(--diy-unit, 1px) * 13);gap:0}.peek .carousel-viewport>button{flex-basis:100%}.peek .carousel-viewport>button.inactive{transform:scale(.92)}.normal{margin:0 calc(var(--diy-unit, 1px) * 10)}</style>
